/* ORBITAL website – js/render.js. 3D view: camera and projection, Canvas 2D rendering, and the Earth map. */

/* --------------------------------------------------------------------------
   7. CAMERA AND PROJECTION  –  rotate → project
   The camera is described by three perpendicular unit axes: R (screen right),
   U (screen up) and T (pointing from the scene towards the camera). To project
   a point we take dot products with these axes, then divide by depth.
   -------------------------------------------------------------------------- */

const VIEW_PRESETS = Object.freeze({
  top: { yaw: 0, tilt: 0 },          // looking straight down the Z axis
  iso: { yaw: -0.62, tilt: 1.02 },   // default three-quarter view
});

const vec = () => ({ x: 0, y: 0, z: 0 });
const cam = {
  mode: 'iso',                 // 'top' | 'iso' | 'follow'
  yaw: VIEW_PRESETS.iso.yaw,   // rotation about the Earth's axis (world Z)
  tilt: VIEW_PRESETS.iso.tilt, // 0 = top-down, π/2 = side view
  followAz: 0, followEl: 0.6,  // follow camera: angle around / above the satellite
  followSat: -1,               // track index being followed
  dist: 1, distGoal: 1,        // camera distance from the target
  target: vec(), targetGoal: vec(),
  R: { x: 1, y: 0, z: 0 }, U: { x: 0, y: 1, z: 0 }, T: { x: 0, y: 0, z: 1 },
  gR: vec(), gU: vec(), gT: vec(),   // goal axes (we ease towards them)
  pos: vec(),                  // camera position in world space
  lastAlong: null,             // last good along-track direction (follow mode)
  f: 800, near: 1,             // focal length in px and near-plane distance
  easeUntil: 0,
  sceneRadius: CLASSIC_DEFAULTS.earthRadius * 1.3,
};
const view = { w: 1, h: 1, dpr: 1, cx: 0, cy: 0, cxGoal: 0, cyGoal: 0, availMin: 400 };

// Axes from yaw/tilt (used by the top-down and isometric views and free rotation).
function axesFromAngles(yaw, tilt, R, U, T) {
  const cy = Math.cos(yaw), sy = Math.sin(yaw), cp = Math.cos(tilt), sp = Math.sin(tilt);
  R.x = cy; R.y = -sy; R.z = 0;
  U.x = sy * cp; U.y = cy * cp; U.z = sp;
  T.x = -sy * sp; T.y = -cy * sp; T.z = cp;
}

// Axes for the follow view: above (radial) and behind (−along-track) the satellite.
function followAxes(px, py, pz, vx, vy, vz, az, el, R, U, T) {
  const r = Math.sqrt(px * px + py * py + pz * pz) || 1;
  const rx = px / r, ry = py / r, rz = pz / r;
  const dot = vx * rx + vy * ry + vz * rz;
  let sx = vx - dot * rx, sy = vy - dot * ry, sz = vz - dot * rz;   // velocity without its radial part
  let sl = Math.sqrt(sx * sx + sy * sy + sz * sz);
  if (sl < 1e-9 && cam.lastAlong) { sx = cam.lastAlong.x; sy = cam.lastAlong.y; sz = cam.lastAlong.z; sl = 1; }
  if (sl < 1e-9) { sx = -ry; sy = rx; sz = 0; sl = Math.sqrt(sx * sx + sy * sy) || 1; if (sl < 1e-9) { sx = 1; sl = 1; } }
  sx /= sl; sy /= sl; sz /= sl;
  cam.lastAlong = { x: sx, y: sy, z: sz };
  const hx = ry * sz - rz * sy, hy = rz * sx - rx * sz, hz = rx * sy - ry * sx;   // orbit normal r × s
  const ce = Math.cos(el), se = Math.sin(el), ca = Math.cos(az), sa = Math.sin(az);
  T.x = rx * se + (-sx * ca + hx * sa) * ce;
  T.y = ry * se + (-sy * ca + hy * sa) * ce;
  T.z = rz * se + (-sz * ca + hz * sa) * ce;
  const rt = rx * T.x + ry * T.y + rz * T.z;
  let ux = rx - rt * T.x, uy = ry - rt * T.y, uz = rz - rt * T.z;
  const ul = Math.sqrt(ux * ux + uy * uy + uz * uz) || 1;
  U.x = ux / ul; U.y = uy / ul; U.z = uz / ul;
  crossInto(U, T, R);                     // R = U × T keeps the axes right-handed
}

function crossInto(a, b, out) {
  const x = a.y * b.z - a.z * b.y, y = a.z * b.x - a.x * b.z, z = a.x * b.y - a.y * b.x;
  out.x = x; out.y = y; out.z = z;
}
function normalise(v) { const l = Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z) || 1; v.x /= l; v.y /= l; v.z /= l; }

// Move the current axes a fraction k of the way to the goal axes, keeping them perpendicular.
function blendAxes(k) {
  const { T, U, R, gT, gU, gR } = cam;
  if (k >= 1 || T.x * gT.x + T.y * gT.y + T.z * gT.z < -0.9) {
    T.x = gT.x; T.y = gT.y; T.z = gT.z; U.x = gU.x; U.y = gU.y; U.z = gU.z; R.x = gR.x; R.y = gR.y; R.z = gR.z;
    return;
  }
  T.x += (gT.x - T.x) * k; T.y += (gT.y - T.y) * k; T.z += (gT.z - T.z) * k; normalise(T);
  U.x += (gU.x - U.x) * k; U.y += (gU.y - U.y) * k; U.z += (gU.z - U.z) * k;
  const d = U.x * T.x + U.y * T.y + U.z * T.z;
  U.x -= d * T.x; U.y -= d * T.y; U.z -= d * T.z; normalise(U);
  crossInto(U, T, R);
}

// Project a world point. Returns false when it is behind the camera.
function project(x, y, z, out) {
  const px = x - cam.target.x, py = y - cam.target.y, pz = z - cam.target.z;
  const u = px * cam.R.x + py * cam.R.y + pz * cam.R.z;   // right
  const v = px * cam.U.x + py * cam.U.y + pz * cam.U.z;   // up
  const w = px * cam.T.x + py * cam.T.y + pz * cam.T.z;   // towards the camera
  const depth = cam.dist - w;
  out.depth = depth;
  if (depth <= cam.near) return false;
  const s = cam.f / depth;                                // perspective divide
  out.x = view.cx + u * s;
  out.y = view.cy - v * s;
  out.s = s;
  return true;
}

// Same, but a point behind the camera is pushed onto the near plane (for the Earth outline).
function projectClamped(x, y, z, out) {
  const px = x - cam.target.x, py = y - cam.target.y, pz = z - cam.target.z;
  const u = px * cam.R.x + py * cam.R.y + pz * cam.R.z;
  const v = px * cam.U.x + py * cam.U.y + pz * cam.U.z;
  const w = px * cam.T.x + py * cam.T.y + pz * cam.T.z;
  const s = cam.f / Math.max(cam.dist - w, cam.near);
  out.x = view.cx + u * s;
  out.y = view.cy - v * s;
}

// Is the point hidden behind the Earth? Ray–sphere test from the camera to the point.
const earthVis = { outside: true, c: 0 };
function hiddenByEarth(x, y, z) {
  if (!earthVis.outside) return false;
  const cx = cam.pos.x, cy = cam.pos.y, cz = cam.pos.z;
  const dx = x - cx, dy = y - cy, dz = z - cz;
  const a = dx * dx + dy * dy + dz * dz;
  const b = 2 * (cx * dx + cy * dy + cz * dz);
  const disc = b * b - 4 * a * earthVis.c;
  if (disc <= 0 || a === 0) return false;
  const t1 = (-b - Math.sqrt(disc)) / (2 * a);
  return t1 > 0 && t1 < 1;
}

function zoomLimits() {
  return cam.mode === 'follow'
    ? [config.watchDist * 1.5, cam.sceneRadius * 6]
    : [config.earthRadius * 1.25, cam.sceneRadius * 25];
}

function defaultDistance() { return cam.sceneRadius * cam.f / (0.45 * view.availMin); }

// Position and velocity of a satellite track at the current (interpolated) time.
const followTmp = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0 };
function trackState(t, out) {
  const run = state.run;
  if (!run || t < 0) return false;
  const i = state.frameIdx;
  const k = run.sats[t].idx[i];
  if (k < 0) return false;
  out.x = interp.sat[k * 3]; out.y = interp.sat[k * 3 + 1]; out.z = interp.sat[k * 3 + 2];
  const s = run.frames[i].sats[k];
  let a = s, b = null, dt = 1;
  if (s.next >= 0) { b = run.frames[i + 1].sats[s.next]; dt = run.ticks[i + 1] - run.ticks[i]; }
  else if (i > 0 && run.sats[t].idx[i - 1] >= 0) { a = run.frames[i - 1].sats[run.sats[t].idx[i - 1]]; b = s; dt = run.ticks[i] - run.ticks[i - 1]; }
  if (b) { out.vx = (b.x - a.x) / dt; out.vy = (b.y - a.y) / dt; out.vz = (b.z - a.z) / dt; }
  else { out.vx = 0; out.vy = 0; out.vz = 0; }
  return true;
}

// Called every frame: work out the goal view, ease towards it, place the camera.
function updateCamera(wallDt, now) {
  const easing = !state.reducedMotion && now < cam.easeUntil;
  const k = easing ? 1 - Math.exp(-wallDt / 0.07) : 1;
  const kz = state.reducedMotion ? 1 : 1 - Math.exp(-wallDt / 0.08);

  if (cam.mode === 'follow' && trackState(cam.followSat, followTmp)) {
    const f = followTmp;
    followAxes(f.x, f.y, f.z, f.vx, f.vy, f.vz, cam.followAz, cam.followEl, cam.gR, cam.gU, cam.gT);
    cam.targetGoal.x = f.x; cam.targetGoal.y = f.y; cam.targetGoal.z = f.z;
  } else if (cam.mode !== 'follow') {
    axesFromAngles(cam.yaw, cam.tilt, cam.gR, cam.gU, cam.gT);
  }
  blendAxes(k);
  cam.target.x += (cam.targetGoal.x - cam.target.x) * k;
  cam.target.y += (cam.targetGoal.y - cam.target.y) * k;
  cam.target.z += (cam.targetGoal.z - cam.target.z) * k;
  cam.dist += (cam.distGoal - cam.dist) * (easing ? k : kz);
  view.cx += (view.cxGoal - view.cx) * kz;
  view.cy += (view.cyGoal - view.cy) * kz;
  cam.near = cam.dist * 0.002;
  cam.pos.x = cam.target.x + cam.T.x * cam.dist;
  cam.pos.y = cam.target.y + cam.T.y * cam.dist;
  cam.pos.z = cam.target.z + cam.T.z * cam.dist;
}

// Back to the default isometric view of the whole scene.
function resetCamera(snap) {
  cam.sceneRadius = state.run ? state.run.sceneRadius : config.earthRadius * 1.3;
  cam.mode = 'iso';
  cam.yaw = VIEW_PRESETS.iso.yaw;
  cam.tilt = VIEW_PRESETS.iso.tilt;
  cam.targetGoal.x = 0; cam.targetGoal.y = 0; cam.targetGoal.z = 0;
  cam.distGoal = defaultDistance();
  if (snap) {
    axesFromAngles(cam.yaw, cam.tilt, cam.R, cam.U, cam.T);
    cam.target.x = 0; cam.target.y = 0; cam.target.z = 0;
    cam.dist = cam.distGoal;
  } else {
    cam.easeUntil = performance.now() + 500;
  }
  updateViewButtons();
}

// View preset buttons: Top-down, Isometric, Follow selected satellite.
function setView(mode) {
  endBurnFocus(false, true);                          // the user chose a view: keep it
  if (!state.run && mode === 'follow') { notify('Load a run first, then pick a satellite to follow.', 'info'); return; }
  if (mode === 'follow') {
    let t = state.selected && state.selected.kind === 'sat' ? state.selected.sat : -1;
    if (t < 0) {
      t = state.run.sats.findIndex((s) => s.idx[state.frameIdx] >= 0);
      if (t < 0) { notify('No satellite is present at this time.', 'warn'); return; }
      focusSat(t);
      notify(`Following ${state.run.sats[t].name}. Pick another satellite to follow it instead.`, 'info');
    }
    cam.followSat = t;
    cam.followAz = 0; cam.followEl = 0.6;
    cam.lastAlong = null;
    cam.mode = 'follow';
    cam.distGoal = Math.max(config.watchDist * UI.followWatchMultiple, config.sectorSize * UI.followSectorMultiple);
  } else {
    const p = VIEW_PRESETS[mode];
    cam.mode = mode; cam.yaw = p.yaw; cam.tilt = p.tilt;
    cam.targetGoal.x = 0; cam.targetGoal.y = 0; cam.targetGoal.z = 0;
    cam.distGoal = defaultDistance();
  }
  cam.easeUntil = performance.now() + 500;
  updateViewButtons();
}

function updateViewButtons() {
  if (!dom.viewButtons) return;
  for (const b of dom.viewButtons) b.setAttribute('aria-pressed', String(b.dataset.view === cam.mode));
}

// Drag to rotate (free angles in top/iso views, angles around the satellite in follow view).
function rotateBy(dx, dy) {
  if (cam.mode === 'follow') {
    cam.followAz -= dx * 0.006;
    cam.followEl = clamp(cam.followEl + dy * 0.006, 0.05, 1.5);
  } else {
    cam.yaw += dx * 0.006;
    cam.tilt = clamp(cam.tilt - dy * 0.006, 0, Math.PI - 0.05);
    if (cam.mode === 'top' && Math.abs(dy) > 0) { cam.mode = 'iso'; updateViewButtons(); }
  }
}

function zoomBy(factor) {
  const [lo, hi] = zoomLimits();
  cam.distGoal = clamp(cam.distGoal * factor, lo, hi);
}


/* --------------------------------------------------------------------------
   9. RENDERING  –  draw → depth-sort → draw (Canvas 2D only)
   -------------------------------------------------------------------------- */

let ctx = null;
let stars = null;
const tmpA = { x: 0, y: 0, depth: 0, s: 0 }, tmpB = { x: 0, y: 0, depth: 0, s: 0 };
const cubePts = Array.from({ length: 8 }, () => ({ x: 0, y: 0, depth: 0, s: 0 }));
const CUBE_EDGES = [[0, 1], [2, 3], [4, 5], [6, 7], [0, 2], [1, 3], [4, 6], [5, 7], [0, 4], [1, 5], [2, 6], [3, 7]];
const CUBE_FACES = [[0, 1, 3, 2], [4, 5, 7, 6], [0, 1, 5, 4], [2, 3, 7, 6], [0, 2, 6, 4], [1, 3, 7, 5]];
const EARTH_SEGMENTS = 180;                  // smooth horizon even in close-ups
const earthPts = new Float64Array(EARTH_SEGMENTS * 2);
const earthN = { x: 0, y: 0, z: 0 }, earthE1 = { x: 0, y: 0, z: 0 }, earthE2 = { x: 0, y: 0, z: 0 };
const AXIS_Z = Object.freeze({ x: 0, y: 0, z: 1 }), AXIS_X = Object.freeze({ x: 1, y: 0, z: 0 });
const drawList = [];          // visible objects of this frame, sorted far → near
const itemPool = [];          // reused item objects (no allocation per frame)

function readColours() {
  const cs = getComputedStyle(document.documentElement);
  for (const name of COLOUR_TOKENS.concat(['--earth-light', '--earth-mid', '--earth-dark', '--atmosphere'])) {
    colours[name] = cs.getPropertyValue(name).trim() || '#ffffff';
  }
  glowSprites.clear();
  for (const name of ['--comm', '--imaging', '--sat-neutral']) glowSprites.set(colours[name], makeGlowSprite(colours[name]));
  const n = parseInt(colours['--atmosphere'].replace('#', ''), 16);
  atmRGB[0] = (n >> 16) & 255; atmRGB[1] = (n >> 8) & 255; atmRGB[2] = n & 255;
}

// A soft round glow, drawn once per colour and reused with drawImage.
function makeGlowSprite(colour) {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, withAlpha(colour, 0.6));
  grad.addColorStop(0.35, withAlpha(colour, 0.22));
  grad.addColorStop(1, withAlpha(colour, 0));
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  return c;
}

function classColour(cls) {
  if (cls === 'Communication') return colours['--comm'];
  if (cls === 'Imaging') return colours['--imaging'];
  return colours['--sat-neutral'];
}
function classVar(cls) {
  if (cls === 'Communication') return 'var(--comm)';
  if (cls === 'Imaging') return 'var(--imaging)';
  return 'var(--sat-neutral)';
}
const riskColour = (r) => colours[RISK_VARS[r]];

// Stars are directions (infinitely far), so only the camera rotation moves them: parallax.
function buildStars() {
  const rnd = mulberry32(7);
  stars = new Float32Array(UI.stars * 7);
  for (let i = 0; i < UI.stars; i++) {
    const z = rnd() * 2 - 1, phi = rnd() * TAU, r = Math.sqrt(1 - z * z);
    const o = i * 7;
    stars[o] = r * Math.cos(phi); stars[o + 1] = r * Math.sin(phi); stars[o + 2] = z;
    stars[o + 3] = 0.6 + Math.pow(rnd(), 3) * 1.3;   // size in px
    stars[o + 4] = 0.2 + rnd() * 0.6;                // brightness
    stars[o + 5] = rnd(); stars[o + 6] = rnd();      // fixed screen spot (reduced motion)
  }
}

function drawStars(now) {
  ctx.fillStyle = '#dbe4ff';
  if (state.reducedMotion) {
    for (let i = 0; i < 260; i++) {
      const o = i * 7;
      ctx.globalAlpha = stars[o + 4];
      ctx.fillRect(stars[o + 5] * view.w, stars[o + 6] * view.h, stars[o + 3], stars[o + 3]);
    }
    ctx.globalAlpha = 1;
    return;
  }
  const drift = now * 0.000003;                      // very slow sky rotation
  const c = Math.cos(drift), s = Math.sin(drift);
  const { R, U, T } = cam;
  for (let i = 0; i < UI.stars; i++) {
    const o = i * 7;
    const x = stars[o] * c - stars[o + 1] * s, y = stars[o] * s + stars[o + 1] * c, z = stars[o + 2];
    const w = x * T.x + y * T.y + z * T.z;
    if (w > -0.05) continue;                         // behind the viewer
    const k = cam.f / -w;
    const sx = view.cx + (x * R.x + y * R.y + z * R.z) * k;
    const sy = view.cy - (x * U.x + y * U.y + z * U.z) * k;
    if (sx < 0 || sy < 0 || sx > view.w || sy > view.h) continue;
    ctx.globalAlpha = stars[o + 4];
    ctx.fillRect(sx, sy, stars[o + 3], stars[o + 3]);
  }
  ctx.globalAlpha = 1;
}

// Earth: the outline of a sphere seen from a point is a circle on the sphere (the
// horizon). We project 72 points of that circle, fill the shape, and add a glow.
function drawEarth() {
  const R = config.earthRadius;
  const C = cam.pos;
  const d2 = C.x * C.x + C.y * C.y + C.z * C.z, d = Math.sqrt(d2);
  earthVis.outside = d > R * 1.0005;
  earthVis.c = d2 - R * R;
  if (!earthVis.outside) return;

  const k = (R * R) / d2;
  const hx = C.x * k, hy = C.y * k, hz = C.z * k;       // centre of the horizon circle
  const rho = R * Math.sqrt(1 - k);                     // its radius
  earthN.x = C.x / d; earthN.y = C.y / d; earthN.z = C.z / d;
  const e1 = earthE1, e2 = earthE2;                     // two directions across the horizon circle
  crossInto(Math.abs(earthN.z) < 0.9 ? AXIS_Z : AXIS_X, earthN, e1); normalise(e1);
  crossInto(earthN, e1, e2);

  let sumX = 0, sumY = 0;
  for (let i = 0; i < EARTH_SEGMENTS; i++) {
    const th = (i / EARTH_SEGMENTS) * TAU, c = Math.cos(th), s = Math.sin(th);
    projectClamped(hx + rho * (c * e1.x + s * e2.x), hy + rho * (c * e1.y + s * e2.y), hz + rho * (c * e1.z + s * e2.z), tmpA);
    earthPts[i * 2] = tmpA.x; earthPts[i * 2 + 1] = tmpA.y;
    sumX += tmpA.x; sumY += tmpA.y;
  }
  const cx = sumX / EARTH_SEGMENTS, cy = sumY / EARTH_SEGMENTS;
  let r = 0;
  for (let i = 0; i < EARTH_SEGMENTS; i++) r += Math.hypot(earthPts[i * 2] - cx, earthPts[i * 2 + 1] - cy);
  r = Math.max(1, r / EARTH_SEGMENTS);

  // atmospheric glow
  const glow = ctx.createRadialGradient(cx, cy, r * 0.96, cx, cy, r * 1.16);
  glow.addColorStop(0, withAlpha(colours['--atmosphere'], 0.34));
  glow.addColorStop(1, withAlpha(colours['--atmosphere'], 0));
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.arc(cx, cy, r * 1.16, 0, TAU); ctx.fill();

  // body: the textured globe when the map is ready, otherwise a shaded disc
  if (earthTex.ready) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < EARTH_SEGMENTS; i++) {
      const x = earthPts[i * 2], y = earthPts[i * 2 + 1];
      if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y;
    }
    const x0 = Math.max(0, Math.floor(minX) - 1), y0 = Math.max(0, Math.floor(minY) - 1);
    const x1 = Math.min(view.w, Math.ceil(maxX) + 1), y1 = Math.min(view.h, Math.ceil(maxY) + 1);
    if (x1 > x0 && y1 > y0) drawTexturedEarth(x0, y0, x1, y1, r);
    ctx.beginPath();
    ctx.moveTo(earthPts[0], earthPts[1]);
    for (let i = 1; i < EARTH_SEGMENTS; i++) ctx.lineTo(earthPts[i * 2], earthPts[i * 2 + 1]);
    ctx.closePath();
    ctx.strokeStyle = withAlpha(colours['--atmosphere'], 0.4);
    ctx.lineWidth = 1.2;
    ctx.stroke();
    return;
  }
  ctx.beginPath();
  ctx.moveTo(earthPts[0], earthPts[1]);
  for (let i = 1; i < EARTH_SEGMENTS; i++) ctx.lineTo(earthPts[i * 2], earthPts[i * 2 + 1]);
  ctx.closePath();
  const body = ctx.createRadialGradient(cx - r * 0.35, cy - r * 0.4, r * 0.05, cx, cy, r * 1.02);
  body.addColorStop(0, colours['--earth-light']);
  body.addColorStop(0.55, colours['--earth-mid']);
  body.addColorStop(1, colours['--earth-dark']);
  ctx.fillStyle = body;
  ctx.fill();
  ctx.strokeStyle = withAlpha(colours['--atmosphere'], 0.45);
  ctx.lineWidth = 1.2;
  ctx.stroke();
}

// ---- Textured Earth -------------------------------------------------------
// The map (section 15) is a JPEG stored as a data URL, so it loads from file://
// and the canvas may read its pixels. It is a generated illustration, not imagery.
const earthTex = { ready: false, w: 0, h: 0, data: null, texels: null };
const earthImg = { canvas: null, g: null, image: null, w: 0, h: 0, hq: false, still: 0,
  last: new Float64Array(17), key: new Float64Array(17) };
const EARTH_PIXELS = { moving: 120000, focus: 70000, still: 650000 };   // pixels ray-traced per redraw
// (focus: burn focus follows the satellite, so the camera never rests and the Earth, a
//  background there, is redrawn every frame; a smaller image keeps those frames cheap)
const atmRGB = [90, 169, 255];
let earthPhase0 = 0;                                        // rotation angle at t = 0

function loadEarthTexture() {
  const img = new Image();
  img.onload = () => {
    const c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const g = c.getContext('2d');
    g.drawImage(img, 0, 0);
    earthTex.data = g.getImageData(0, 0, c.width, c.height).data;
    earthTex.texels = new Uint32Array(earthTex.data.buffer);   // one number per texel (RGBA bytes)
    earthTex.w = c.width; earthTex.h = c.height;
    earthTex.ready = true;
    earthImg.last[0] = NaN;                                 // force a redraw
  };
  img.onerror = () => console.warn('Earth map could not be decoded; drawing the plain globe.');
  img.src = EARTH_TEXTURE;
}

// Fast polynomial atan2 and asin (Abramowitz & Stegun style). Their errors (< 0.0003 rad)
// are about 1/15 of a texel, but they are roughly twice as fast as Math.atan2 / Math.asin,
// which matters when they run for every Earth pixel.
function fastAtan2(y, x) {
  const ax = Math.abs(x), ay = Math.abs(y);
  const a = (ax > ay ? ay / ax : ax / (ay || 1)) || 0, s = a * a;
  let r = ((-0.0464964749 * s + 0.15931422) * s - 0.327622764) * s * a + a;
  if (ay > ax) r = 1.57079637 - r;
  if (x < 0) r = 3.14159274 - r;
  return y < 0 ? -r : r;
}
function fastAsin(x) {
  const ax = Math.abs(x);
  const r = 1.5707963 - Math.sqrt(1 - ax) * (1.5707288 + ax * (-0.2121144 + ax * (0.074261 - 0.0187293 * ax)));
  return x < 0 ? -r : r;
}

// Greenwich sidereal angle at a UTC time (ms since 1970): where Greenwich points in space.
function gmstRadians(ms) {
  const days = ms / 86400000 + 2440587.5 - 2451545.0;      // days since J2000.0
  const deg = 280.46061837 + 360.98564736629 * days;
  return ((((deg % 360) + 360) % 360) * Math.PI) / 180;
}
function computeEarthPhase() {
  earthPhase0 = 0;
  if (config.mode !== 'real') return;
  const ms = Date.parse(config.startUtc || (config.snapshotDate ? `${config.snapshotDate}T00:00:00Z` : ''));
  if (Number.isFinite(ms)) earthPhase0 = gmstRadians(ms);
}
// The Earth's rotation angle now.
function earthRotation() {
  const t = state.run ? state.playTick * config.dt : 0;
  return earthPhase0 + EARTH_ROTATION_RATE * t;
}

// Reuse the last Earth image while the view is unchanged; sharpen it once the view is still.
function drawTexturedEarth(x0, y0, x1, y1, screenRadius) {
  const bw = x1 - x0, bh = y1 - y0, theta = earthRotation();
  const k = earthImg.key, last = earthImg.last;
  k[0] = cam.pos.x; k[1] = cam.pos.y; k[2] = cam.pos.z; k[3] = cam.R.x; k[4] = cam.R.y; k[5] = cam.R.z;
  k[6] = cam.U.x; k[7] = cam.U.y; k[8] = cam.U.z; k[9] = view.cx; k[10] = view.cy; k[11] = cam.f;
  k[12] = x0; k[13] = y0; k[14] = bw; k[15] = bh; k[16] = theta;
  let same = true;
  for (let i = 0; i < 16; i++) if (!(Math.abs(k[i] - last[i]) <= 1e-7 * (1 + Math.abs(k[i])))) { same = false; break; }
  if (same && Math.abs(theta - last[16]) > (TAU / earthTex.w) * 0.5) same = false;   // turned by half a texel
  // magnified map (close-up views): blend 4 texels instead of picking 1, so it is smooth not blocky
  const smooth = (4 * screenRadius) / earthTex.w > 1.2;
  if (!same) { earthImg.still = 0; renderEarthImage(x0, y0, bw, bh, theta, false, smooth); last.set(k); }
  else if (++earthImg.still === 3 && !earthImg.hq) renderEarthImage(x0, y0, bw, bh, theta, true, smooth);
  // clip to the exact horizon outline so the edge is smooth whatever the image resolution
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(earthPts[0], earthPts[1]);
  for (let i = 1; i < EARTH_SEGMENTS; i++) ctx.lineTo(earthPts[i * 2], earthPts[i * 2 + 1]);
  ctx.closePath();
  ctx.clip();
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(earthImg.canvas, 0, 0, earthImg.w, earthImg.h, x0, y0, bw, bh);
  ctx.restore();
}

// Ray-trace the Earth into a small image: for each pixel, a ray from the camera hits the
// sphere; the hit point gives latitude/longitude, which picks a texel; then lighting.
// Kept tight because it runs for every Earth pixel: plain local numbers, a lookup table
// instead of asin, and one 32-bit write per pixel.
const LAT_ROWS = 8192;
let latRowLUT = null;                       // height on the sphere (z) → texture row (fractional)
function renderEarthImage(x0, y0, bw, bh, theta, hq, smooth) {
  const budget = hq ? EARTH_PIXELS.still : (focus.active || cam.mode === 'follow') ? EARTH_PIXELS.focus : EARTH_PIXELS.moving;
  let scale = Math.min(hq ? view.dpr : 1, Math.sqrt(budget / Math.max(1, bw * bh)));
  // Close up (follow, burn focus) the map is the limit, not the screen: one map pixel can
  // cover hundreds of screen pixels, so ray-tracing every screen pixel only blends the
  // same few texels. Render at most ~3 image pixels per map pixel at the nearest surface
  // point (world units per screen pixel there = height / focal length); the smooth
  // texture sampling and the upscaling look the same, at a fraction of the cost.
  const nearest = Math.max(1e-6, Math.hypot(cam.pos.x, cam.pos.y, cam.pos.z) - config.earthRadius);
  const texel = (TAU * config.earthRadius) / earthTex.w;               // one map pixel at the equator
  const mapScale = (3 * nearest) / (cam.f * texel);                     // image px per screen px needed
  scale = Math.min(scale, Math.max(mapScale, 96 / Math.max(bw, bh)));   // never below ~96 px across
  const w = Math.max(1, Math.round(bw * scale)), h = Math.max(1, Math.round(bh * scale));
  if (!earthImg.canvas) { earthImg.canvas = document.createElement('canvas'); earthImg.g = earthImg.canvas.getContext('2d'); }
  if (earthImg.canvas.width < w || earthImg.canvas.height < h) {
    earthImg.canvas.width = Math.max(w, earthImg.canvas.width);
    earthImg.canvas.height = Math.max(h, earthImg.canvas.height);
  }
  if (!earthImg.image || earthImg.image.width !== w || earthImg.image.height !== h) {
    earthImg.image = earthImg.g.createImageData(w, h);
    earthImg.pixels = new Uint32Array(earthImg.image.data.buffer);   // one number per pixel (RGBA bytes)
  }
  const tw = earthTex.w, th = earthTex.h, tex = earthTex.texels;
  if (!latRowLUT || latRowLUT.th !== th) {
    latRowLUT = new Float32Array(LAT_ROWS + 1);
    for (let i = 0; i <= LAT_ROWS; i++) {
      const z = (i / LAT_ROWS) * 2 - 1;
      latRowLUT[i] = Math.min(th - 1, (0.5 - Math.asin(z) / Math.PI) * th);
    }
    latRowLUT.th = th;
  }
  const px = earthImg.pixels, R = config.earthRadius, f = cam.f;
  const cx = cam.pos.x, cy = cam.pos.y, cz = cam.pos.z, cc = cx * cx + cy * cy + cz * cz - R * R;
  const rx = cam.R.x, ry = cam.R.y, rz = cam.R.z, ux = cam.U.x, uy = cam.U.y, uz = cam.U.z;
  const tx = cam.T.x, ty = cam.T.y, tz = cam.T.z;
  // light from the viewer's upper left (the planet always looks lit, like the reference photo)
  let lx = tx * 0.8 + ux * 0.45 - rx * 0.35, ly = ty * 0.8 + uy * 0.45 - ry * 0.35, lz = tz * 0.8 + uz * 0.45 - rz * 0.35;
  const ll = Math.sqrt(lx * lx + ly * ly + lz * lz); lx /= ll; ly /= ll; lz /= ll;
  let hx = lx + tx, hy = ly + ty, hz = lz + tz;                                // half-way vector for sun glint
  const hl = Math.sqrt(hx * hx + hy * hy + hz * hz); hx /= hl; hy /= hl; hz /= hl;
  const ct = Math.cos(-theta), st = Math.sin(-theta), invR = 1 / R;
  const ar = atmRGB[0], ag = atmRGB[1], ab = atmRGB[2];
  const limbColour = 0xff000000 | (((ab * 0.8) | 0) << 16) | (((ag * 0.8) | 0) << 8) | ((ar * 0.8) | 0);
  const sxStep = bw / w, syStep = bh / h, invTau = 1 / TAU;
  let o = 0;
  for (let j = 0; j < h; j++) {
    const v = -(y0 + (j + 0.5) * syStep - view.cy) / f;
    const bx = ux * v - tx, by = uy * v - ty, bz = uz * v - tz;              // ray = R*u + U*v − T
    for (let i = 0; i < w; i++, o++) {
      const u = (x0 + (i + 0.5) * sxStep - view.cx) / f;
      const dx = rx * u + bx, dy = ry * u + by, dz = rz * u + bz;
      const a = dx * dx + dy * dy + dz * dz, b = 2 * (cx * dx + cy * dy + cz * dz);
      const disc = b * b - 4 * a * cc;
      if (disc <= 0) {                                                        // ray misses the Earth...
        const tc = -b / (2 * a);                                              // ...but passes just above it?
        const qx = cx + tc * dx, qy = cy + tc * dy, qz = cz + tc * dz;
        px[o] = tc > 0 && qx * qx + qy * qy + qz * qz < R * R * 1.0016 ? limbColour : 0;   // fill the edge pixel; the clip trims it
        continue;
      }
      const t = (-b - Math.sqrt(disc)) / (2 * a);
      if (t <= 0) { px[o] = 0; continue; }
      const nx = (cx + t * dx) * invR, ny = (cy + t * dy) * invR, nz = (cz + t * dz) * invR;
      // into the Earth's own rotating frame, then longitude → column and height → row
      let tu = fastAtan2(nx * st + ny * ct, nx * ct - ny * st) * invTau + 0.5;
      tu -= Math.floor(tu);
      let zi = ((nz + 1) * 0.5 * LAT_ROWS) | 0;
      if (zi < 0) zi = 0; else if (zi > LAT_ROWS) zi = LAT_ROWS;
      let r, g, bl;
      if (!smooth) {                                                          // nearest texel
        const texel = tex[(latRowLUT[zi] | 0) * tw + ((tu * tw) | 0)];
        r = texel & 255; g = (texel >> 8) & 255; bl = (texel >> 16) & 255;
      } else {                                                                // bilinear: blend 4 texels
        const fu = tu * tw - 0.5, fv = latRowLUT[zi] - 0.5;
        let i0 = Math.floor(fu), j0 = fv < 0 ? 0 : fv | 0;
        const wu = fu - i0, wv = fv < 0 ? 0 : fv - j0;
        if (i0 < 0) i0 += tw;
        const i1 = i0 + 1 >= tw ? 0 : i0 + 1, j1 = j0 + 1 >= th ? th - 1 : j0 + 1;
        const t00 = tex[j0 * tw + i0], t10 = tex[j0 * tw + i1], t01 = tex[j1 * tw + i0], t11 = tex[j1 * tw + i1];
        const w00 = (1 - wu) * (1 - wv), w10 = wu * (1 - wv), w01 = (1 - wu) * wv, w11 = wu * wv;
        r = (t00 & 255) * w00 + (t10 & 255) * w10 + (t01 & 255) * w01 + (t11 & 255) * w11;
        g = ((t00 >> 8) & 255) * w00 + ((t10 >> 8) & 255) * w10 + ((t01 >> 8) & 255) * w01 + ((t11 >> 8) & 255) * w11;
        bl = ((t00 >> 16) & 255) * w00 + ((t10 >> 16) & 255) * w10 + ((t01 >> 16) & 255) * w01 + ((t11 >> 16) & 255) * w11;
      }
      const ndl = nx * lx + ny * ly + nz * lz;
      const lit = 0.16 + 0.92 * (ndl > 0 ? ndl : 0);
      r *= lit; g *= lit; bl *= lit;
      if (bl > r + 18 && bl > g) {                                            // water: sun glint
        const nh = nx * hx + ny * hy + nz * hz;
        if (nh > 0.93) { const sp = Math.pow(nh, 70) * 120; r += sp; g += sp; bl += sp; }
      }
      const rim = 1 + (nx * dx + ny * dy + nz * dz) / Math.sqrt(a);         // 0 facing us, 1 at the limb
      const haze = rim * rim * rim * 0.8;                                   // atmosphere near the edge
      r += (ar - r) * haze; g += (ag - g) * haze; bl += (ab - bl) * haze;
      px[o] = 0xff000000 | ((bl > 255 ? 255 : bl) << 16) | ((g > 255 ? 255 : g) << 8) | (r > 255 ? 255 : r);
    }
  }
  earthImg.g.putImageData(earthImg.image, 0, 0);
  earthImg.w = w; earthImg.h = h; earthImg.hq = hq;
}

// Each satellite's whole path, sampled at up to UI.pathPoints written frames (built once).
function buildOrbitPaths(run) {
  for (const track of run.sats) {
    const present = [];
    for (let i = 0; i < run.frames.length; i++) if (track.idx[i] >= 0) present.push(i);
    const step = Math.max(1, Math.ceil(present.length / UI.pathPoints));
    const picks = [];
    for (let j = 0; j < present.length; j += step) picks.push(present[j]);
    if (present.length && picks[picks.length - 1] !== present[present.length - 1]) picks.push(present[present.length - 1]);
    track.path = new Float64Array(picks.length * 3);
    picks.forEach((i, j) => {
      const s = run.frames[i].sats[track.idx[i]];
      track.path[j * 3] = s.x; track.path[j * 3 + 1] = s.y; track.path[j * 3 + 2] = s.z;
    });
  }
}

// Dotted orbit paths for every satellite.
// Speed: the browser's dashed lines are very slow to draw over long paths (with all
// six CelesTrak files they took ~160 ms a frame), so each dot is a small square placed
// every few pixels along the path, and all dots of one colour are filled at once.
// The finished layer is kept as an image and reused while the camera, the window and
// the selection are unchanged: the paths are fixed in space, so during normal
// playback they cost one image copy per frame.
const pathLayer = { canvas: null, g: null, run: null, key: new Float64Array(22), last: new Float64Array(22), still: 0, fine: false };

// Add the dots of one path (x, y, z triples, every `stride` numbers) to g's current path.
// Only the part of each segment inside the window gets dots: when the camera is close
// (burn focus), one orbit is millions of pixels long on screen, and placing dots along
// all of it took hundreds of milliseconds a frame. The spacing is unchanged on screen.
function tracePathDots(g, p, stride, gap, size) {
  const h = size / 2, m = 8;                                             // margin around the window
  const X0 = -m, Y0 = -m, X1 = view.w + m, Y1 = view.h + m;
  let px = 0, py = 0, have = false, carry = 0;
  for (let j = 0; j < p.length; j += stride) {
    const ok = project(p[j], p[j + 1], p[j + 2], tmpA) && !hiddenByEarth(p[j], p[j + 1], p[j + 2]);
    if (!ok) { have = false; continue; }                                       // behind the Earth or the camera
    const x = tmpA.x, y = tmpA.y;
    if (!have) {
      if (x >= X0 && x <= X1 && y >= Y0 && y <= Y1) g.rect(x - h, y - h, size, size);
      have = true; carry = 0; px = x; py = y; continue;
    }
    const dx = x - px, dy = y - py, len = Math.hypot(dx, dy);
    if (len > 0) {
      const first = gap - carry;                                           // distance to the first dot
      // visible part of the segment, as [a, b] in distance along it (Liang–Barsky clip)
      let t0 = 0, t1 = 1;
      const clip = (pp, q) => {
        if (pp === 0) return q >= 0;
        const r = q / pp;
        if (pp < 0) { if (r > t1) return false; if (r > t0) t0 = r; }
        else { if (r < t0) return false; if (r < t1) t1 = r; }
        return true;
      };
      if (clip(-dx, px - X0) && clip(dx, X1 - px) && clip(-dy, py - Y0) && clip(dy, Y1 - py)) {
        const a = t0 * len, b = t1 * len;
        let k = Math.max(0, Math.ceil((a - first) / gap));
        for (let t = first + k * gap; t <= b; t += gap) g.rect(px + (dx * t) / len - h, py + (dy * t) / len - h, size, size);
      }
      // carry on the spacing as if every dot had been placed
      carry = len >= first ? len - (first + Math.floor((len - first) / gap) * gap) : carry + len;
    }
    px = x; py = y;
  }
}

// All paths except skipA and skipB, one fill per colour.
function drawPathDotsInto(g, skipA, skipB, gap, budget = UI.pathBudget) {
  const run = state.run, n = run.sats.length;
  const perPath = Math.max(40, Math.floor(budget / Math.max(1, n)));          // points used per path
  const byColour = new Map();
  for (let t = 0; t < n; t++) {
    if (t === skipA || t === skipB) continue;
    const col = classColour(run.sats[t].cls);
    if (!byColour.has(col)) byColour.set(col, []);
    byColour.get(col).push(t);
  }
  g.globalAlpha = n > 200 ? 0.32 : n > 30 ? 0.42 : 0.55;
  for (const [col, list] of byColour) {
    g.fillStyle = col;
    g.beginPath();
    for (const t of list) {
      const p = run.sats[t].path;
      if (p && p.length >= 6) tracePathDots(g, p, 3 * Math.max(1, Math.ceil(p.length / 3 / perPath)), gap, 1.5);
    }
    g.fill();
  }
  g.globalAlpha = 1;
}

function drawOrbitPaths() {
  const run = state.run;
  const sel = state.selected && state.selected.kind === 'sat' ? state.selected.sat : -1;
  const follow = cam.followSat;
  // everything the projection and the picture depend on
  const k = pathLayer.key, last = pathLayer.last;
  k[0] = cam.target.x; k[1] = cam.target.y; k[2] = cam.target.z;
  k[3] = cam.R.x; k[4] = cam.R.y; k[5] = cam.R.z; k[6] = cam.U.x; k[7] = cam.U.y; k[8] = cam.U.z;
  k[9] = cam.T.x; k[10] = cam.T.y; k[11] = cam.T.z; k[12] = cam.dist; k[13] = cam.f;
  k[14] = view.cx; k[15] = view.cy; k[16] = view.w; k[17] = view.h; k[18] = view.dpr;
  k[19] = sel; k[20] = follow; k[21] = run.sats.length;
  // still = unchanged within a hundredth of a pixel (the camera eases in tiny steps)
  let same = pathLayer.run === run;
  for (let i = 0; same && i < 22; i++) {
    const tol = i >= 14 ? 0.01 : 1e-7 * (1 + Math.abs(k[i]));
    if (!(Math.abs(k[i] - last[i]) <= tol)) same = false;
  }
  if (!pathLayer.canvas) { pathLayer.canvas = document.createElement('canvas'); pathLayer.g = pathLayer.canvas.getContext('2d'); }
  const c = pathLayer.canvas, g = pathLayer.g;
  // While the camera moves the layer is redrawn every frame with sparser dots; once it
  // has been still for 3 frames it is redrawn once in full detail and then reused.
  const redraw = (fine) => {
    const W = Math.round(view.w * view.dpr), H = Math.round(view.h * view.dpr);
    if (c.width !== W || c.height !== H) { c.width = W; c.height = H; }
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, W, H);
    g.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
    drawPathDotsInto(g, sel, follow, fine ? 7 : 12, fine ? UI.pathBudget : UI.pathBudget / 2.5);   // moving: coarser
    pathLayer.fine = fine;
  };
  if (!same) {
    const wasStill = pathLayer.still > 0 || pathLayer.run !== run;      // a single change (a click, a resize): draw it fine at once
    pathLayer.still = 0;
    redraw(wasStill);
    last.set(k); pathLayer.run = run;
  } else if (++pathLayer.still === 3 && !pathLayer.fine) redraw(true);
  ctx.drawImage(c, 0, 0, view.w, view.h);
  // the selected and followed satellites, live and brighter, every point
  for (const t of new Set([sel, follow])) {
    if (t < 0 || t >= run.sats.length) continue;
    const track = run.sats[t];
    if (!track.path || track.path.length < 6) continue;
    ctx.fillStyle = classColour(track.cls);
    ctx.globalAlpha = 0.95;
    ctx.beginPath(); tracePathDots(ctx, track.path, 3, 6, 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
}

// Real mode: a faint equator so the inclination of each orbit is readable.
function drawEquator() {
  if (!earthVis.outside) return;
  const R = config.earthRadius * 1.002, C = cam.pos;
  ctx.strokeStyle = withAlpha(colours['--comm'], 0.4);
  ctx.lineWidth = 1;
  ctx.setLineDash([5, 6]);
  ctx.beginPath();
  let prev = false;
  for (let i = 0; i <= 144; i++) {
    const th = (i / 144) * TAU, x = R * Math.cos(th), y = R * Math.sin(th);
    const facing = x * (C.x - x) + y * (C.y - y) + 0 * C.z > 0;   // surface point faces the camera
    const ok = facing && project(x, y, 0, tmpA);
    if (ok) { if (prev) ctx.lineTo(tmpA.x, tmpA.y); else ctx.moveTo(tmpA.x, tmpA.y); }
    prev = ok;
  }
  ctx.stroke();
  ctx.setLineDash([]);
}

// Red-zone sectors: translucent wireframe cubes with edge = sector_size.
function drawRedZones() {
  const run = state.run, S = config.sectorSize, col = colours['--critical'];
  const sel = state.selected && state.selected.kind === 'sat' ? state.selected.sat : -2;
  for (const zone of run.zones) {
    if (zone.tick > state.playTick) break;            // zones are sorted by declaration tick
    if (!zone.corner) continue;
    const [x0, y0, z0] = zone.corner;
    if (hiddenByEarth(x0 + S / 2, y0 + S / 2, z0 + S / 2)) continue;
    // project two opposite corners first: a cube only a few pixels wide is drawn as a dot
    if (!project(x0, y0, z0, cubePts[0]) || !project(x0 + S, y0 + S, z0 + S, cubePts[7])) continue;
    const size = Math.hypot(cubePts[7].x - cubePts[0].x, cubePts[7].y - cubePts[0].y);
    if (size < 4) {
      ctx.fillStyle = col; ctx.globalAlpha = 0.7;
      ctx.fillRect(cubePts[0].x - 1, cubePts[0].y - 1, 2, 2);
      ctx.globalAlpha = 1;
      continue;
    }
    let ok = true;
    for (let i = 1; i < 7; i++) {
      if (!project(x0 + (i & 1) * S, y0 + ((i >> 1) & 1) * S, z0 + ((i >> 2) & 1) * S, cubePts[i])) { ok = false; break; }
    }
    if (!ok) continue;
    ctx.fillStyle = col;
    ctx.globalAlpha = 0.05;
    for (const f of CUBE_FACES) {
      ctx.beginPath();
      ctx.moveTo(cubePts[f[0]].x, cubePts[f[0]].y);
      for (let j = 1; j < 4; j++) ctx.lineTo(cubePts[f[j]].x, cubePts[f[j]].y);
      ctx.closePath(); ctx.fill();
    }
    ctx.globalAlpha = 0.75;
    ctx.strokeStyle = col;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const [a, b] of CUBE_EDGES) { ctx.moveTo(cubePts[a].x, cubePts[a].y); ctx.lineTo(cubePts[b].x, cubePts[b].y); }
    ctx.stroke();
    ctx.globalAlpha = 1;
    if ((size > 16 || zone.satIdx === sel) && zone.sat) {
      let top = cubePts[0];
      for (let i = 1; i < 8; i++) if (cubePts[i].y < top.y) top = cubePts[i];
      label(`Red zone (${zone.sat})`, top.x + 4, top.y - 8, col, '500 10.5px');
    }
  }
}

// Fading trail over the last UI.trailFrames written frames.
function drawTrails() {
  const run = state.run, i = state.frameIdx;
  ctx.lineWidth = 1.4;
  ctx.lineCap = 'round';
  const many = run.sats.length > UI.maxTrails;                     // hundreds of trails: unreadable and slow
  const sel = state.selected && state.selected.kind === 'sat' ? state.selected.sat : -1;
  for (let t = 0; t < run.sats.length; t++) {
    if (many && t !== sel && t !== cam.followSat) continue;
    const track = run.sats[t], cur = track.idx[i];
    if (cur < 0) continue;
    ctx.strokeStyle = classColour(track.cls);
    let pa = tmpA, pb = tmpB;
    const ax = interp.sat[cur * 3], ay = interp.sat[cur * 3 + 1], az = interp.sat[cur * 3 + 2];
    let aOk = project(ax, ay, az, pa) && !hiddenByEarth(ax, ay, az);
    for (let m = 0; m < UI.trailFrames; m++) {
      const j = i - m;
      if (j < 0 || track.idx[j] < 0) break;
      const o = run.frames[j].sats[track.idx[j]];
      const bOk = project(o.x, o.y, o.z, pb) && !hiddenByEarth(o.x, o.y, o.z);
      if (aOk && bOk) {
        ctx.globalAlpha = 0.55 * (1 - m / UI.trailFrames);
        ctx.beginPath(); ctx.moveTo(pa.x, pa.y); ctx.lineTo(pb.x, pb.y); ctx.stroke();
      }
      const swap = pa; pa = pb; pb = swap; aOk = bOk;
    }
  }
  ctx.globalAlpha = 1;
}

// Collect visible objects, then sort far → near (painter's algorithm).
function buildDrawList() {
  const run = state.run, fr = run.frames[state.frameIdx];
  drawList.length = 0;
  let p = 0;
  for (let k = 0; k < fr.sats.length; k++) p = addItem(p, 0, k, interp.sat);
  for (let k = 0; k < fr.debris.length; k++) p = addItem(p, 1, k, interp.deb);
  drawList.sort(byDepth);
}
function addItem(p, kind, k, arr) {
  const x = arr[k * 3], y = arr[k * 3 + 1], z = arr[k * 3 + 2];
  if (!project(x, y, z, tmpA)) return p;
  if (tmpA.x < -40 || tmpA.y < -40 || tmpA.x > view.w + 40 || tmpA.y > view.h + 40) return p;
  if (hiddenByEarth(x, y, z)) return p;
  let it = itemPool[p];
  if (!it) it = itemPool[p] = { kind: 0, k: 0, x: 0, y: 0, depth: 0 };
  it.kind = kind; it.k = k; it.x = tmpA.x; it.y = tmpA.y; it.depth = tmpA.depth;
  drawList.push(it);
  return p + 1;
}
const byDepth = (a, b) => b.depth - a.depth;

// Thin risk-coloured line from each satellite to its nearest debris inside watch_dist.
function drawRiskLines() {
  const fr = state.run.frames[state.frameIdx];
  ctx.lineWidth = 1.3;
  for (let k = 0; k < fr.sats.length; k++) {
    const s = fr.sats[k];
    if (s.nearDebIdx < 0 || !(s.nearDeb < config.watchDist)) continue;
    const a = k * 3, b = s.nearDebIdx * 3;
    if (!project(interp.sat[a], interp.sat[a + 1], interp.sat[a + 2], tmpA)) continue;
    if (!project(interp.deb[b], interp.deb[b + 1], interp.deb[b + 2], tmpB)) continue;
    if (hiddenByEarth(interp.sat[a], interp.sat[a + 1], interp.sat[a + 2])) continue;
    ctx.strokeStyle = riskColour(s.risk);
    ctx.globalAlpha = 0.9;
    ctx.beginPath(); ctx.moveTo(tmpA.x, tmpA.y); ctx.lineTo(tmpB.x, tmpB.y); ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function label(text, x, y, colour, weight) {
  ctx.font = `${weight || '600 11.5px'} Inter, system-ui, sans-serif`;
  ctx.textBaseline = 'middle';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(5, 10, 26, 0.8)';
  ctx.strokeText(text, x, y);
  ctx.fillStyle = colour;
  ctx.fillText(text, x, y);
}

// Little wrench badge for satellites under repair.
function drawWrench(x, y) {
  const c = colours['--sat-neutral'];
  ctx.fillStyle = 'rgba(10, 16, 34, 0.92)';
  ctx.strokeStyle = c;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(x, y, 6.5, 0, TAU); ctx.fill(); ctx.stroke();
  ctx.save();
  ctx.translate(x, y); ctx.rotate(Math.PI / 4);
  ctx.lineWidth = 1.5; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, 3.4); ctx.lineTo(0, -0.4); ctx.stroke();
  ctx.beginPath(); ctx.arc(0, -2.1, 1.8, -Math.PI / 2 + 0.75, Math.PI * 1.5 - 0.75); ctx.stroke();
  ctx.restore();
}

// Debris first, then satellites on top (far to near).
// Speed: thousands of debris dots are grouped by colour and style, so each group is a
// single fill or stroke instead of one per dot.
const debrisGroups = new Map();
function drawObjects() {
  const run = state.run, fr = run.frames[state.frameIdx];
  const sel = state.selected;
  for (const list of debrisGroups.values()) list.length = 0;
  let hoverItem = null, selItem = null;
  for (const it of drawList) {
    if (it.kind !== 1) continue;
    const d = fr.debris[it.k];
    const r = clamp(2.1 * cam.dist / it.depth, 1.3, 3.6);
    const col = d.risk >= 0 ? riskColour(d.risk) : colours[d.src === 'real' ? '--debris-real' : '--debris-synthetic'];
    const key = (d.src === 'real' ? 'f' : 's') + col;            // filled dot (real) or hollow ring (synthetic)
    let list = debrisGroups.get(key);
    if (!list) debrisGroups.set(key, list = []);
    list.push(it.x, it.y, r);
    if (hover.kind === 1 && hover.id === d.idKey) hoverItem = { it, r };
    if (sel && sel.kind === 'debris' && sel.idKey === d.idKey) selItem = { it, r, d };
  }
  ctx.lineWidth = 1.2;
  for (const [key, list] of debrisGroups) {
    if (!list.length) continue;
    const col = key.slice(1);
    if (key[0] === 'f') {
      // filled (real) debris: a dot of 2–4 px looks the same as a square and is far cheaper
      ctx.fillStyle = col;
      let big = false;
      ctx.beginPath();                                             // all small dots of this colour: one fill
      for (let i = 0; i < list.length; i += 3) {
        const r = list[i + 2];
        if (r >= 2.4) { big = true; continue; }
        const q = r * 1.75;
        ctx.rect(list[i] - q / 2, list[i + 1] - q / 2, q, q);
      }
      ctx.fill();
      if (big) {                                                   // close-up: real circles
        ctx.beginPath();
        for (let i = 0; i < list.length; i += 3) {
          if (list[i + 2] < 2.4) continue;
          ctx.moveTo(list[i] + list[i + 2], list[i + 1]);
          ctx.arc(list[i], list[i + 1], list[i + 2], 0, TAU);
        }
        ctx.fill();
      }
    } else {                                                       // synthetic: hollow rings
      ctx.strokeStyle = col;
      ctx.beginPath();
      for (let i = 0; i < list.length; i += 3) {
        ctx.moveTo(list[i] + list[i + 2], list[i + 1]);
        ctx.arc(list[i], list[i + 1], list[i + 2], 0, TAU);
      }
      ctx.stroke();
    }
  }
  if (hoverItem) {                                                  // under the pointer
    ctx.strokeStyle = withAlpha(colours['--text'], 0.7); ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(hoverItem.it.x, hoverItem.it.y, hoverItem.r + 4, 0, TAU); ctx.stroke();
  }
  if (selItem) {
    const { it, r, d } = selItem;
    ctx.strokeStyle = colours['--text']; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(it.x, it.y, r + 6, 0, TAU); ctx.stroke();
    label(`#${d.idKey}`, it.x + r + 9, it.y, colours['--text'], '600 11px');
  }
  for (const it of drawList) {
    if (it.kind === 1) continue;
    {
      const s = fr.sats[it.k];
      const col = classColour(run.sats[s.ti].cls);
      if (s.disabled) {
        ctx.strokeStyle = withAlpha(colours['--sat-neutral'], 0.8);
        ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.arc(it.x, it.y, 5, 0, TAU); ctx.stroke();
        drawWrench(it.x + 9, it.y - 9);
      } else {
        if (fr.sats.length <= UI.maxGlows) ctx.drawImage(glowSprites.get(col) || glowSprites.get(colours['--sat-neutral']), it.x - 16, it.y - 16, 32, 32);
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(it.x, it.y, 3.8, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.85)';
        ctx.beginPath(); ctx.arc(it.x, it.y, 1.5, 0, TAU); ctx.fill();
      }
      if (hover.kind === 0 && hover.id === s.name && !(sel && sel.kind === 'sat' && sel.sat === s.ti)) {
        ctx.strokeStyle = withAlpha(colours['--text'], 0.7); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(it.x, it.y, 9, 0, TAU); ctx.stroke();
      }
      if (sel && sel.kind === 'sat' && sel.sat === s.ti) {
        ctx.strokeStyle = colours['--text']; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.arc(it.x, it.y, 11, 0, TAU); ctx.stroke();
      }
    }
  }
  drawSatLabels(fr, sel);
}

// Every satellite's name. Order: selected, hovered, then nearest to the camera first.
// A name that would cover one already placed is left out until zooming in or turning
// the view separates them (overlapping names would be unreadable).
const labelWidths = new Map();
function drawSatLabels(fr, sel) {
  const items = [];
  for (let i = drawList.length - 1; i >= 0; i--) if (drawList[i].kind === 0) items.push(drawList[i]);   // near → far
  const rank = (it) => {
    const s = fr.sats[it.k];
    if (sel && sel.kind === 'sat' && sel.sat === s.ti) return 0;
    if (hover.kind === 0 && hover.id === s.name) return 1;
    return 2;
  };
  items.sort((a, b) => rank(a) - rank(b));        // stable: keeps near → far within each rank
  const cell = 64, grid = new Map(), placed = [];
  const overlaps = (x0, y0, x1, y1) => {
    for (let gx = Math.floor(x0 / cell); gx <= Math.floor(x1 / cell); gx++) {
      for (let gy = Math.floor(y0 / cell); gy <= Math.floor(y1 / cell); gy++) {
        const list = grid.get(gx * 100003 + gy);
        if (list) for (const k of list) {
          const q = placed[k];
          if (x0 < q[2] && x1 > q[0] && y0 < q[3] && y1 > q[1]) return true;
        }
      }
    }
    return false;
  };
  const add = (x0, y0, x1, y1) => {
    const k = placed.push([x0, y0, x1, y1]) - 1;
    for (let gx = Math.floor(x0 / cell); gx <= Math.floor(x1 / cell); gx++) {
      for (let gy = Math.floor(y0 / cell); gy <= Math.floor(y1 / cell); gy++) {
        const key = gx * 100003 + gy;
        if (!grid.has(key)) grid.set(key, []);
        grid.get(key).push(k);
      }
    }
  };
  ctx.font = '600 11px Inter, system-ui, sans-serif';
  for (const it of items) {
    const s = fr.sats[it.k], r0 = rank(it);
    let w = labelWidths.get(s.name);
    if (w === undefined) { w = ctx.measureText(s.name).width; labelWidths.set(s.name, w); }
    const x = it.x + 9, y = it.y + (s.disabled ? 9 : -9);
    const box = [x - 2, y - 7, x + w + 2, y + 7];
    if (r0 === 2 && overlaps(...box)) continue;
    add(...box);
    const strong = r0 < 2;
    label(s.name, x, y, strong ? colours['--text'] : colours['--text-dim'], strong ? '650 12px' : '600 11px');
  }
}

// Expanding ring when a satellite performs an evasive burn.
function drawPulses(now) {
  const run = state.run;
  for (let i = pulses.length - 1; i >= 0; i--) {
    const p = pulses[i];
    const age = (now - p.start) / UI.pulseMs;
    if (age >= 1 || p.sat < 0) { pulses.splice(i, 1); continue; }
    const k = run.sats[p.sat].idx[state.frameIdx];
    if (k < 0) continue;
    const x = interp.sat[k * 3], y = interp.sat[k * 3 + 1], z = interp.sat[k * 3 + 2];
    if (!project(x, y, z, tmpA) || hiddenByEarth(x, y, z)) continue;
    const r = state.reducedMotion ? 16 : 6 + 30 * (1 - Math.pow(1 - age, 3));
    ctx.globalAlpha = state.reducedMotion ? 0.8 : 0.9 * (1 - age);
    ctx.strokeStyle = colours['--tag-decision'];
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(tmpA.x, tmpA.y, r, 0, TAU); ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

// One full frame of the scene.
function drawScene(now) {
  ctx.clearRect(0, 0, view.w, view.h);
  drawStars(now);
  drawEarth();
  if (!state.run) return;
  if (config.mode === 'real') drawEquator();
  drawOrbitPaths();
  drawRedZones();
  if (!state.reducedMotion) drawTrails();
  buildDrawList();
  drawRiskLines();
  drawObjects();
  drawBurnFocus(now);
  drawPulses(now);
}

// If live blur makes playback stutter (weak GPU), switch the panels to solid
// backgrounds once. Measured only while playing, in 2-second windows.
const fpsGuard = { frames: 0, start: 0, slow: 0, done: false };
function watchFrameRate(now) {
  if (fpsGuard.done || !state.playing || document.hidden || now - ui.loadedAt < 3000) {
    fpsGuard.frames = 0; fpsGuard.start = now;
    return;
  }
  fpsGuard.frames++;
  const elapsed = now - fpsGuard.start;
  if (elapsed < 2000) return;
  const fps = (fpsGuard.frames * 1000) / elapsed;
  fpsGuard.frames = 0; fpsGuard.start = now;
  fpsGuard.slow = fps < UI.minFps ? fpsGuard.slow + 1 : 0;
  if (fpsGuard.slow >= 1) {
    fpsGuard.done = true;
    document.body.classList.add('solid-glass');
    notify(`Playback ran at about ${Math.round(fps)} fps, so the panels now use solid backgrounds instead of live blur.`, 'info');
  }
}

// The animation loop.
let lastNow = 0;
function loop(now) {
  const wallDt = lastNow ? Math.min(0.1, (now - lastNow) / 1000) : 0;
  lastNow = now;
  if (state.run) {
    const before = state.playTick;
    if (state.playing) advance(wallDt);
    syncTime();
    if (state.playTick > before && state.playing) {
      spawnPulses(before, state.playTick, now);
      if (!focus.active) maybeStartBurnFocus(before, state.playTick, now);
    }
    computeInterp();
  }
  updateCamera(wallDt, now);
  drawScene(now);
  if (state.run) { refreshPanels(now); watchFrameRate(now); }
  updateHover(now);
  requestAnimationFrame(loop);
}

// ---- Details card for the object under the pointer --------------------------
// Mouse: the card follows whatever is under the cursor, re-checked every frame because
// objects move. Touch: tapping an object pins the card to it for a few seconds.
const hover = {
  mouse: false, x: 0, y: 0,          // last mouse position over the scene
  kind: -1, id: '',                  // object shown now (0 sat / 1 debris, name or debris id)
  pinKind: -1, pinId: '', pinUntil: 0,
  frame: -1, htmlAt: 0, w: 0, h: 0, shown: false,
};
const TIP_PIN_MS = 5000;

// Speed from this written frame to the next one, in units (or km) per second.
function objectSpeed(o, list, i) {
  const run = state.run;
  if (o.next < 0 || !run.frames[i + 1]) return NaN;
  const p = run.frames[i + 1][list][o.next];
  const d = Math.sqrt((p.x - o.x) ** 2 + (p.y - o.y) ** 2 + (p.z - o.z) ** 2);
  return d / ((run.ticks[i + 1] - run.ticks[i]) * config.dt);
}

function tipHtml(kind, o, fr) {
  const run = state.run, i = state.frameIdx, u = config.units;
  const row = (label, value, colourVar) => `<dt>${label}</dt><dd${colourVar ? ` style="--vc:${colourVar}"` : ''}>${escapeHtml(value)}</dd>`;
  const r = Math.sqrt(o.x * o.x + o.y * o.y + o.z * o.z);
  const speed = objectSpeed(o, kind === 0 ? 'sats' : 'debris', i);
  let html, rows = '';
  rows += row('Altitude', fmtDist(r - config.earthRadius));
  rows += row('Speed', Number.isFinite(speed) ? `${speed.toFixed(2)} ${u}/s` : '–');
  if (kind === 0) {
    const track = run.sats[o.ti];
    const cls = track.cls ? `${track.cls} satellite` : 'Satellite, class not recorded';
    html = `<div class="tip-head"><span class="tip-dot${o.disabled ? ' hollow' : ''}" style="--c:${classVar(track.cls)}"></span>
      <strong>${escapeHtml(o.name)}</strong><span class="status-tag${o.disabled ? ' repair' : ''}">${o.disabled ? 'UNDER REPAIR' : 'ONLINE'}</span></div>
      <p class="tip-sub">${escapeHtml(cls)}, ${o.src === 'real' ? 'from real orbital data' : 'synthetic'}</p>`;
    if (o.nearDebIdx >= 0) {
      const d = fr.debris[o.nearDebIdx];
      rows += row('Nearest debris', `#${d.idKey}, ${fmtDist(o.nearDeb)} ${RISK_NAMES[o.risk]}`, `var(${RISK_VARS[o.risk]})`);
    } else rows += row('Nearest debris', 'none');
    if (o.nearSatIdx >= 0) rows += row('Nearest satellite', `${fr.sats[o.nearSatIdx].name}, ${fmtDist(o.nearSat)}`);
    if (o.fuel !== null) rows += row('Fuel', `${fmt2(o.fuel)} kg`);
    if (o.battery !== null) rows += row('Battery', `${fmt2(o.battery)}%`);
    if (o.software !== null) rows += row('Software', `${fmt2(o.software)}%`);
  } else {
    html = `<div class="tip-head"><span class="tip-dot${o.src === 'real' ? '' : ' hollow'}" style="--c:var(${o.src === 'real' ? '--debris-real' : '--debris-synthetic'})"></span>
      <strong>Debris #${escapeHtml(o.idKey)}</strong></div>
      <p class="tip-sub">${o.src === 'real' ? 'Real (catalogued) debris' : 'Synthetic debris from the chaos engine'}</p>`;
    if (o.nearSatIdx >= 0) {
      const near = fr.sats[o.nearSatIdx];
      const inWatch = o.risk >= 0;
      rows += row('Nearest satellite', `${near.name}, ${fmtDist(o.nearSat)}${inWatch ? ` ${RISK_NAMES[o.risk]}` : ''}`, inWatch ? `var(${RISK_VARS[o.risk]})` : '');
    }
  }
  rows += row('Position', `${fmt2(o.x)}, ${fmt2(o.y)}, ${fmt2(o.z)}`);
  return `${html}<dl class="tip-grid">${rows}</dl><p class="tip-foot">Values at tick ${fr.tick}. ${kind === 0 ? 'Click to open its details.' : 'Click to select it.'}</p>`;
}

// The drawn item for a given object, if it is visible this frame.
function findDrawn(kind, id) {
  const fr = currentFrame();
  for (const it of drawList) {
    if (it.kind !== kind) continue;
    if ((kind === 0 ? fr.sats[it.k].name : fr.debris[it.k].idKey) === id) return it;
  }
  return null;
}

function hideTip() {
  if (hover.shown) { dom.hoverTip.hidden = true; hover.shown = false; }
  hover.kind = -1; hover.id = '';
  dom.scene.classList.remove('over-object');
}

// Called every frame after drawing: find the object, refresh the card, place it.
function updateHover(now) {
  if (!state.run || ui.dragging) { hideTip(); return; }
  let it = null, pinned = false;
  if (hover.pinId && now < hover.pinUntil) { it = findDrawn(hover.pinKind, hover.pinId); pinned = true; }
  else if (hover.mouse) it = pickAt(hover.x, hover.y);
  if (!it) { hideTip(); return; }
  const fr = currentFrame(), o = it.kind === 0 ? fr.sats[it.k] : fr.debris[it.k];
  const id = it.kind === 0 ? o.name : o.idKey;
  const tip = dom.hoverTip;
  // rebuild the text only when the object or written frame changes (or 4×/s for live values)
  if (id !== hover.id || it.kind !== hover.kind || state.frameIdx !== hover.frame || now - hover.htmlAt > 250) {
    tip.innerHTML = tipHtml(it.kind, o, fr);
    hover.kind = it.kind; hover.id = id; hover.frame = state.frameIdx; hover.htmlAt = now;
    if (!hover.shown) { tip.hidden = false; hover.shown = true; }
    hover.w = tip.offsetWidth; hover.h = tip.offsetHeight;
  }
  dom.scene.classList.toggle('over-object', !pinned);
  // beside the pointer (or the tapped object), flipped to stay on screen
  const ax = pinned ? it.x : hover.x, ay = pinned ? it.y : hover.y, gap = 16;
  let x = ax + gap, y = ay + gap;
  if (x + hover.w > view.w - 8) x = ax - gap - hover.w;
  if (y + hover.h > view.h - 8) y = ay - gap - hover.h;
  tip.style.transform = `translate(${Math.max(8, Math.round(x))}px, ${Math.max(8, Math.round(y))}px)`;
}

// Click → nearest drawn object (satellites win ties).
function pickAt(x, y) {
  let best = null, bestScore = Infinity;
  for (const it of drawList) {
    const d = Math.hypot(it.x - x, it.y - y);
    if (d > (it.kind === 0 ? 18 : 10)) continue;
    const score = d - (it.kind === 0 ? 6 : 0);
    if (score < bestScore) { bestScore = score; best = it; }
  }
  return best;
}


/* --------------------------------------------------------------------------
   15. EARTH MAP  –  1600 × 800 equirectangular JPEG stored as a data URL
   Longitude −180° on the left, latitude +90° at the top. It was generated
   offline (tools/make_earth_texture.py) from hand-traced coastlines, colours
   sampled from a NASA-style "Blue Marble" photo, procedural relief and clouds.
   It is an illustration, not satellite imagery. A data URL keeps the project
   at three files and lets the canvas read the pixels even from file://.
   -------------------------------------------------------------------------- */
const EARTH_TEXTURE = 'data:image/jpeg;base64,';
